#!/bin/bash
# the ansible environment, with SASL/PLAIN authentication and SSL encryption on every listener (sasl_protocol: plain,
# ssl_enabled: true in the inventory, certificates generated by cp-ansible)
DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null && pwd )"
export ANSIBLE_SECURITY="sasl-ssl"
exec "${DIR}/../ansible/start.sh" "$@"
